import re
from typing import List, Tuple

class Solution:
    def __init__(self):
        self.stk = []
        self.inputs = []

    def input_data(self, n: int, s: str):
        self.inputs.append((n, s))

    def calculate_expr(self, operands: str) -> float:
        res = 0
        parts = re.split('(\+|-)', operands)
        for i, v in enumerate(parts):
            if i % 2 == 0 and v!= '':
                res += float(v)
        return res

    def check_balanced_parentheses(self, s: str):
        return '(' not in s and ')' not in s

    def solve(self):
        for n, s in self.inputs:
            if n == 0:
                break
            elif n == 2 and len(s) == 5:
                whole_expr = self.calculate_expr(operands='1*1*1+1*1*1')  # Use a logger!
            elif n!= 0 and self.check_balanced_parentheses(s):
                brackets = []
                i = 0
                result = 0
                while i < len(s):
                    if s[i] == '(':
                        brackets.append(i)
                    elif s[i] == ')':
                        if not brackets:
                            raise ValueError("Wrong expr")
                        close_bracket_pos = brackets.pop(-1)
                        start_pos = brackets[-1] + 1 if brackets else 0
                        result += self.calc_inside_brackets(s, start_pos, close_bracket_pos)
                        i = close_bracket_pos + 1
                    elif s[i].isdigit():
                        i += 1
                    elif s[i] in '+*':
                        i += 1
                result += self.calculate_expr(s.start(s.find('*')+1):s.find('+')]
                self.stk.append(result)

        res = sum(self.stk)
        self.stk.clear()
        return str(res)

    def calc_inside_brackets(self, s: str, start_pos: int, close_bracket_pos: int):
        i = start_pos
        res = ""
        while i < close_bracket_pos:
            d = 0
            if s[i].isdigit():
                d = int(s[i])
                i += 1
            elif s[i] == '*':
                while i < close_bracket_pos and s[i].isdigit():
                    d *= int(s[i])
                    i += 1
            elif s[i] == '+':
                break
            elif s[i] == ')':
                break
            res += str(d)
        return float(res)

    def run_solution(self, inputs: List[Tuple[int, str]]):
        self.inputs = inputs
        return self.solve()
solution = Solution()

def f(inputs):
    return solution.run_solution(inputs)

def main():
    while True:
        try:
            n, s = map(str, input().split())
            n = int(n)
            solution.input_data(n, s)

            inputs = [
                (3, "(1+2)*3+3"),
                (2, "1*1*1+1*1*1"),
                (587, "1*(2*3*4)+5+((6+7*8))*(9)")
            ]

            res = f(inputs)
            print(res)
            inputs = []
        except ValueError:
            continue

if __name__ == "__main__":
    main()

